from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Indicators import (
    SimpleMovingAverage,
    RelativeStrengthIndex,
    MovingAverageType,
    IndicatorDataPoint
)


class ExactStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.symbols[0]
        self.aapl = self.symbols[1]

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        available_bars = {}

        for symbol in self.symbols:
            if symbol in data.Bars:
                available_bars[symbol] = data.Bars[symbol]

        if self.spy in available_bars:
            spy_bar = available_bars[self.spy]
            self.spy_sma.Update(
                IndicatorDataPoint(spy_bar.EndTime, spy_bar.Close)
            )

        if self.aapl in available_bars:
            aapl_bar = available_bars[self.aapl]
            self.aapl_rsi.Update(
                IndicatorDataPoint(aapl_bar.EndTime, aapl_bar.Close)
            )

        if self.aapl in available_bars:
            aapl_close = available_bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        if not all(symbol in available_bars for symbol in self.symbols):
            self._update_previous_values(available_bars)
            return

        if self.IsWarmingUp:
            self._update_previous_values(available_bars)
            return

        spy_close = available_bars[self.spy].Close
        aapl_close = available_bars[self.aapl].Close

        spy_buy = False
        spy_sell = False

        if (
            self.spy_sma.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        ):
            current_spy_sma = self.spy_sma.Current.Value

            spy_buy = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_close > current_spy_sma
            )

            spy_sell = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_close < current_spy_sma
            )

        aapl_buy = self.aapl_red_streak >= 3
        aapl_sell = self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60

        if self.spy_lot > 0 and spy_sell:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_sell:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_buy:
            shares = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.spy_lot = shares

        if self.aapl_lot == 0 and aapl_buy:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.aapl_lot = shares

        self._update_previous_values(available_bars)

    def _update_previous_values(self, available_bars):
        if self.spy in available_bars:
            spy_close = available_bars[self.spy].Close
            self.previous_spy_close = spy_close

            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

        if self.aapl in available_bars:
            self.previous_aapl_close = available_bars[self.aapl].Close

