from AlgorithmImports import *


class TwoSlotStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.SetWarmUp(100, Resolution.Daily)

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending = {
            "A": False,
            "B": False
        }

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, data):
        available = {
            self.spy: self.spy in data.Bars,
            self.aapl: self.aapl in data.Bars,
            self.ibm: self.ibm in data.Bars,
            self.bac: self.bac in data.Bars,
            self.aig: self.aig in data.Bars
        }

        if available[self.aapl]:
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        spy_close = None
        spy_sma_value = None

        if available[self.spy] and self.spy_sma.IsReady:
            spy_close = data.Bars[self.spy].Close
            spy_sma_value = self.spy_sma.Current.Value

        complete_day = all(available.values())

        if complete_day and not self.IsWarmingUp:
            self._evaluate_strategy_a(spy_close, spy_sma_value)
            self._evaluate_strategy_b()

        if spy_close is not None and spy_sma_value is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma_value

    def _evaluate_strategy_a(self, spy_close, spy_sma_value):
        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        crossed_above = (
            self.previous_spy_close <= self.previous_spy_sma
            and spy_close > spy_sma_value
        )

        crossed_below = (
            self.previous_spy_close >= self.previous_spy_sma
            and spy_close < spy_sma_value
        )

        if self.lots["A"] > 0 and not self.pending["A"] and crossed_below:
            self._submit_sell("A", self.spy, self.lots["A"],
                              "Strategy A sell: SPY crossed below SMA100")

        elif self.lots["A"] == 0 and not self.pending["A"] and crossed_above:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )

            if quantity > 0:
                self._submit_buy(
                    "A",
                    self.spy,
                    quantity,
                    "Strategy A buy: SPY crossed above SMA100"
                )

    def _evaluate_strategy_b(self):
        if not self.aapl_rsi.IsReady:
            return

        if self.lots["B"] > 0 and not self.pending["B"]:
            if self.aapl_rsi.Current.Value > 60:
                self._submit_sell(
                    "B",
                    self.aapl,
                    self.lots["B"],
                    "Strategy B sell: AAPL RSI above 60"
                )

        elif self.lots["B"] == 0 and not self.pending["B"]:
            if self.aapl_red_streak >= 3:
                close = self.Securities[self.aapl].Close

                if self.Portfolio.Cash >= 20000 and close > 0:
                    quantity = int(20000 / close)

                    if quantity > 0:
                        self._submit_buy(
                            "B",
                            self.aapl,
                            quantity,
                            "Strategy B buy: AAPL red for 3 consecutive days"
                        )

    def _submit_buy(self, strategy, symbol, quantity, tag):
        self.pending[strategy] = True
        self.MarketOrder(symbol, quantity, tag=tag)

    def _submit_sell(self, strategy, symbol, quantity, tag):
        if quantity <= 0:
            return

        self.pending[strategy] = True
        self.MarketOrder(symbol, -quantity, tag=tag)

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        ]:
            return

        strategy = None

        if order_event.Symbol == self.spy:
            strategy = "A"
        elif order_event.Symbol == self.aapl:
            strategy = "B"

        if strategy is None:
            return

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ]:
            fill_quantity = int(order_event.FillQuantity)

            if fill_quantity > 0:
                self.lots[strategy] += fill_quantity
            elif fill_quantity < 0:
                self.lots[strategy] = max(
                    0,
                    self.lots[strategy] + fill_quantity
                )

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        ]:
            self.pending[strategy] = False

