                self.previous_spy_sma = current_spy_sma

        if aapl_close is not None:
            self.previous_aapl_close = aapl_close

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        quantity = int(orderEvent.FillQuantity)

        if orderEvent.Symbol == self.spy:
            self.spy_lot = max(0, self.spy_lot + quantity)
        elif orderEvent.Symbol == self.aapl:
            self.aapl_lot = max(0, self.aapl_lot + quantity)

