from AlgorithmImports import *


class DailyCrossAndStreakAlgorithm(QCAlgorithm):

    SMA_PERIOD = 14
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = SimpleMovingAverage("SPY_SMA", self.SMA_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(
            "AAPL_RSI",
            self.RSI_PERIOD,
            MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.pending_orders = {}

        self.SetWarmUp(30, Resolution.Daily)

    def OnData(self, data: Slice):
        current_time = self.Time

        if self.spy in data.Bars:
            spy_close = data.Bars[self.spy].Close
            self.spy_sma.Update(current_time, spy_close)

        if self.aapl in data.Bars:
            aapl_close = data.Bars[self.aapl].Close
            self.aapl_rsi.Update(current_time, aapl_close)

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if self.IsWarmingUp:
            if self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value

            if self.spy in data.Bars:
                self.previous_spy_close = data.Bars[self.spy].Close

            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_sma = self.spy_sma.Current.Value
        spy_close = data.Bars[self.spy].Close if self.spy in data.Bars else None

        spy_crossed_above = (
            spy_close is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > spy_sma
        )

        spy_crossed_below = (
            spy_close is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < spy_sma
        )

        all_symbols_present = all(symbol in data.Bars for symbol in self.symbols)

        if all_symbols_present:
            aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

            if self.strategy_a_lot > 0 and spy_crossed_below:
                self._submit_sell("A", self.spy, self.strategy_a_lot)

            if self.strategy_b_lot > 0 and aapl_rsi_above_60:
                self._submit_sell("B", self.aapl, self.strategy_b_lot)

            if self.strategy_a_lot == 0 and spy_crossed_above:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    self._submit_buy("A", self.spy, quantity)

            if (
                self.strategy_b_lot == 0
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20000
            ):
                aapl_close = data.Bars[self.aapl].Close
                quantity = int(20000 / aapl_close)

                if quantity > 0:
                    self._submit_buy("B", self.aapl, quantity)

        if self.spy in data.Bars:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = spy_sma

    def _submit_buy(self, strategy, symbol, quantity):
        if strategy in self.pending_orders:
            return

        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[strategy] = {
            "order_id": ticket.OrderId,
            "direction": "buy"
        }

    def _submit_sell(self, strategy, symbol, quantity):
        if strategy in self.pending_orders or quantity <= 0:
            return

        ticket = self.MarketOrder(symbol, -quantity)
        self.pending_orders[strategy] = {
            "order_id": ticket.OrderId,
            "direction": "sell"
        }

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = None
        order_info = None

        for candidate, info in self.pending_orders.items():
            if info["order_id"] == order_event.OrderId:
                strategy = candidate
                order_info = info
                break

        if strategy is None:
            return

        if order_event.Status in [
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ]:
            fill_quantity = abs(order_event.FillQuantity)

            if order_info["direction"] == "buy":
                if strategy == "A":
                    self.strategy_a_lot += fill_quantity
                else:
                    self.strategy_b_lot += fill_quantity
            else:
                if strategy == "A":
                    self.strategy_a_lot = max(
                        0,
                        self.strategy_a_lot - fill_quantity
                    )
                else:
                    self.strategy_b_lot = max(
                        0,
                        self.strategy_b_lot - fill_quantity
                    )

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]:
            del self.pending_orders[strategy]

